package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Converts persistent world pressures into reviewable Barbara proposals. Never mutates PC resources, prices, damage or rewards by itself. */
public final class BarbaraWorldConsequencePlanner{
 private BarbaraWorldConsequencePlanner(){}
 public static JSONArray propose(JSONObject aggregate,int day){JSONArray out=new JSONArray();try{if(aggregate==null)return out;JSONObject eco=aggregate.optJSONObject("economy");if(eco!=null){java.util.Iterator<String>it=eco.keys();while(it.hasNext()){String region=it.next();JSONObject e=eco.optJSONObject(region);if(e==null)continue;int p=e.optInt("market_pressure",50);if(p>=70)out.put(proposal("economy_pressure",region,day,"scarcity_or_inflation_review",p));else if(p<=30)out.put(proposal("economy_pressure",region,day,"surplus_or_deflation_review",p));}}JSONArray ms=aggregate.optJSONArray("missions");if(ms!=null)for(int i=0;i<ms.length();i++){JSONObject m=ms.optJSONObject(i);if(m!=null&&"overdue".equals(m.optString("status")))out.put(proposal("mission_overdue",m.optString("key"),day,"deadline_consequence_review",100));}JSONObject npcs=aggregate.optJSONObject("npc_graphs");if(npcs!=null){java.util.Iterator<String>ni=npcs.keys();while(ni.hasNext()){String npc=ni.next();JSONObject ns=npcs.optJSONObject(npc);JSONArray cs=ns==null?null:ns.optJSONArray("commitments");if(cs==null)continue;for(int i=0;i<cs.length();i++){JSONObject c=cs.optJSONObject(i);if(c!=null&&c.optBoolean("consequence_pending",false))out.put(proposal("npc_commitment_due",npc+":"+c.optString("key"),day,"npc_commitment_review",Math.min(100,40+c.optInt("overdue_days",0)*5)));}}}JSONObject fs=aggregate.optJSONObject("factions");if(fs!=null){java.util.Iterator<String>fi=fs.keys();while(fi.hasNext()){String faction=fi.next();JSONObject f=fs.optJSONObject(faction);JSONArray ts=f==null?null:f.optJSONArray("treaties");if(ts==null)continue;for(int i=0;i<ts.length();i++){JSONObject t=ts.optJSONObject(i);if(t!=null&&t.optBoolean("consequence_pending",false))out.put(proposal("treaty_expired",faction+":"+t.optString("key"),day,"diplomatic_consequence_review",55));}}}JSONObject pol=aggregate.optJSONObject("politics");if(pol!=null){JSONArray ds=pol.optJSONArray("decrees");if(ds!=null)for(int i=0;i<ds.length();i++){JSONObject d=ds.optJSONObject(i);if(d!=null&&d.optBoolean("consequence_pending",false))out.put(proposal("decree_expired",d.optString("key"),day,"political_expiry_review",50));}if(pol.optJSONArray("timeline")!=null&&pol.optJSONArray("timeline").length()>0)out.put(proposal("political_change","world",day,"political_ripple_review",50));}JSONObject patron=aggregate.optJSONObject("group_patron");if(patron!=null){JSONArray as=patron.optJSONArray("assignments");if(as!=null)for(int i=0;i<as.length();i++){JSONObject a=as.optJSONObject(i);if(a!=null&&a.optBoolean("consequence_pending",false))out.put(proposal("patron_assignment_overdue",a.optString("key"),day,"patron_consequence_review",Math.min(100,45+a.optInt("overdue_days",0)*5)));}}JSONObject cooking=aggregate.optJSONObject("cooking_state");if(cooking!=null&&cooking.optBoolean("restock_due",false))out.put(proposal("cooking_restock_due","cook_pouch",day,"restock_resource_review",35));JSONObject crafts=aggregate.optJSONObject("crafting_projects");if(crafts!=null){java.util.Iterator<String>ci=crafts.keys();while(ci.hasNext()){String id=ci.next();JSONObject cp=crafts.optJSONObject(id);if(cp==null)continue;if(cp.optBoolean("overdue",false))out.put(proposal("crafting_overdue",id,day,"crafting_deadline_review",Math.min(100,30+cp.optInt("overdue_days",0)*5)));if("awaiting_authorized_resolution".equals(cp.optString("status")))out.put(proposal("crafting_resolution",id,day,"authorized_output_review",50));}}JSONObject hazards=aggregate.optJSONObject("environmental_hazards");if(hazards!=null){java.util.Iterator<String>hi=hazards.keys();while(hi.hasNext()){String id=hi.next();JSONObject h=hazards.optJSONObject(id);if(h!=null&&h.optBoolean("pending_barbara_review",false))out.put(proposal("environmental_hazard",id,day,"source_bound_natural_hazard_review",50));}}JSONObject regions=aggregate.optJSONObject("supernatural_regions");if(regions!=null){java.util.Iterator<String>ri=regions.keys();while(ri.hasNext()){String id=ri.next();JSONObject r=regions.optJSONObject(id);if(r!=null&&r.optBoolean("pending_barbara_review",false))out.put(proposal("supernatural_region_effect",id,day,"source_bound_region_effect_review",55));}}JSONObject phenomena=aggregate.optJSONObject("magical_phenomena");if(phenomena!=null){java.util.Iterator<String>pi=phenomena.keys();while(pi.hasNext()){String id=pi.next();JSONObject p=phenomena.optJSONObject(id);if(p!=null&&p.optBoolean("pending_barbara_review",false))out.put(proposal("magical_phenomenon_effect",id,day,"source_bound_phenomenon_review",50));if(p!=null&&"mimic_colony".equals(p.optString("kind"))&&p.optBoolean("bargain_pending",false))out.put(proposal("mimic_colony_bargain",id,day,"mimic_colony_bargain_review",45));}}JSONArray downtime=BarbaraDowntimeResolutionPlanner.propose(aggregate,day);for(int i=0;i<downtime.length();i++){JSONObject q=downtime.optJSONObject(i);if(q!=null)out.put(q);}}catch(Exception ignored){}return out;}
 private static JSONObject proposal(String type,String subject,int day,String action,int severity){JSONObject o=new JSONObject();try{o.put("type",type).put("subject",subject).put("day",Math.max(1,day)).put("proposal",action).put("severity",severity).put("requires_barbara_review",true).put("auto_mutation_allowed",false);}catch(Exception ignored){}return o;}
}
